;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_feature_instance_rate_rule_approve (staging_id STRING, approver STRING, approve_notes VARIANT DEFAULT NULL)RETURNS STRINGLANGUAGE SQLAS $$BEGIN  -- Load staging row  LET s VARIANT := (SELECT OBJECT_CONSTRUCT(*) FROM AI_FEATURE_HUB.rate_rules_staging WHERE staging_id = :staging_id);  IF s IS NULL THENRETURN NULL;  END IF;  LET rule_id STRING := s:rule_payload:rule_id::STRING;  -- Upsert into active rules  MERGE INTO AI_FEATURE_HUB.rate_rules tgt  USING (SELECT :rule_id AS rule_id, :s AS payload) src  ON tgt.rule_id = src.rule_id  WHEN MATCHED THEN UPDATE SET rule_payload = src.payload, active = TRUE, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (rule_id, rule_payload, active, created_at) VALUES (src.rule_id, src.payload, TRUE, CURRENT_TIMESTAMP());  -- Mark staging row approved  UPDATE AI_FEATURE_HUB.rate_rules_staging SET status = &#39;APPROVED&#39;, approved_by = :approver, approved_at = CURRENT_TIMESTAMP(), approval_notes = :approve_notes WHERE staging_id = :staging_id;  RETURN rule_id;END;$$;

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_feature_instance_rate_rule_reject (staging_id STRING, approver STRING, reason STRING)RETURNS STRINGLANGUAGE SQLAS $$BEGIN  UPDATE AI_FEATURE_HUB.rate_rules_staging  SET status = &#39;REJECTED&#39;, approved_by = :approver, approved_at = CURRENT_TIMESTAMP(), approval_notes = :reason  WHERE staging_id = :staging_id;  INSERT INTO AI_FEATURE_HUB.rate_rules_staging_archive (staging_id, archived_at, archive_reason, payload)  SELECT staging_id, CURRENT_TIMESTAMP(), :reason, rule_payload FROM AI_FEATURE_HUB.rate_rules_staging WHERE staging_id = :staging_id;  RETURN :staging_id;END;$$;
