CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.CALCULATE_TIERED_COST (usage_amount NUMBER, tiers VARIANT)RETURNS NUMBERLANGUAGE SQLAS $$-- tiers: array of objects {limit: NUMBER, rate: NUMBER}, compute piecewise costDECLARE remaining NUMBER := :usage_amount;DECLARE cost NUMBER := 0;FOR t IN (SELECT VALUE FROM TABLE(FLATTEN(INPUT =&gt; :tiers))) DO  DECLARE lim NUMBER := t.value:limit::NUMBER;  DECLARE rate NUMBER := t.value:rate::NUMBER;  DECLARE take NUMBER := CASE WHEN remaining &lt;= lim THEN remaining ELSE lim END;  cost := cost + (take * rate);  remaining := remaining - take;  IF remaining &lt;= 0 THEN BREAK; END IF;END FOR;RETURN cost;$$;

