CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.RUN_BILLING_PREVIEW (run_id STRING, account_id STRING, billing_date DATE)RETURNS VARIANTLANGUAGE SQLAS $$WITH usage_agg AS (  SELECT u.account_id,u.feature_key,SUM(u.usage_amount) AS total_usage  FROM AI_FEATURE_HUB.TENANT_FEATURE_USAGE u  WHERE u.account_id = :account_id AND u.usage_ts::DATE &lt;= :billing_date  GROUP BY u.account_id,u.feature_key),applied_rates AS (  SELECT ua.account_id,ua.feature_key,ra.rate_type,ra.rate_value,ua.total_usage  FROM usage_agg ua  JOIN AI_FEATURE_HUB.RATE_RULES rr ON rr.feature_key = ua.feature_key AND rr.effective_from &lt;= :billing_date AND (rr.effective_to IS NULL OR rr.effective_to &gt;= :billing_date)  JOIN AI_FEATURE_HUB.RATE_RULE_TEMPLATES ra ON ra.template_id = rr.template_id)SELECT OBJECT_CONSTRUCT(  &#39;run_id&#39;, :run_id,  &#39;account_id&#39;, :account_id,  &#39;billing_date&#39;, :billing_date,  &#39;lines&#39;, ARRAY_AGG(OBJECT_CONSTRUCT( &#39;feature_key&#39;, feature_key, &#39;rate_type&#39;, rate_type, &#39;rate_value&#39;, rate_value, &#39;usage&#39;, total_usage, &#39;line_total&#39;, CASE WHEN rate_type=&#39;per_unit&#39; THEN total_usage * rate_value WHEN rate_type=&#39;flat&#39; THEN rate_value ELSE total_usage * rate_value END  ))) FROM applied_rates;$$;

Purpose: Persist a committed billing run including computed lines; idempotent (skips IF run_id exists).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PERSIST_BILLING_RUN (run_id STRING, account_id STRING, billing_date DATE, payload VARIANT)RETURNS STRINGLANGUAGE SQLAS $$MERGE INTO AI_FEATURE_HUB.BILLING_RUN tgtUSING (SELECT :run_id AS run_id) src ON tgt.run_id = src.run_idWHEN MATCHED THEN UPDATE SET status=&#39;COMMITTED&#39;, last_updated = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT(run_id, account_id, billing_date, payload, status, created_at)VALUES(:run_id, :account_id, :billing_date, :payload, &#39;COMMITTED&#39;, CURRENT_TIMESTAMP());-- Insert line itemsINSERT INTO AI_FEATURE_HUB.BILLING_LINE_ITEM(line_id, run_id, account_id, feature_key, usage_amount, rate_value, line_total, created_at)SELECT GENERATE_UUID(), :run_id, :account_id, v.value:feature_key::STRING, v.value:usage::NUMBER, v.value:rate_value::NUMBER, v.value:line_total::NUMBER, CURRENT_TIMESTAMP()FROM LATERAL FLATTEN(INPUT =&gt; :payload:lines) v;RETURN :run_id;$$;

Purpose: Reconcile billing runs to usage aggregates AND produce discrepancy report rows.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.CREATE_RATE_RULE_STAGING (staging_id STRING, template_id STRING, feature_key STRING, org_id STRING, effective_from DATE, effective_to DATE, payload VARIANT, created_by STRING)RETURNS STRINGLANGUAGE SQLAS $$MERGE INTO AI_FEATURE_HUB.RATE_RULES_STAGING tgtUSING (SELECT :staging_id AS staging_id) src ON tgt.staging_id = src.staging_idWHEN MATCHED THEN UPDATE SET template_id = :template_id, feature_key = :feature_key, effective_from = :effective_from, effective_to = :effective_to, payload = :payload, updated_by = :created_by, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT (staging_id, template_id, feature_key, org_id, effective_from, effective_to, payload, created_by, created_at)VALUES (:staging_id, :template_id, :feature_key, :org_id, :effective_from, :effective_to, :payload, :created_by, CURRENT_TIMESTAMP());RETURN :staging_id;$$;

Purpose: Approve a staged rate rule AND move it INTO active RATE_RULES table (idempotent).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.APPLY_RATE_RULES_TO_ACCOUNT (account_id STRING, as_of DATE)RETURNS STRINGLANGUAGE SQLAS $$INSERT INTO AI_FEATURE_HUB.ACCOUNT_RATE_SNAPSHOT(snapshot_id, account_id, feature_key, payload, snapshot_at)SELECT GENERATE_UUID(), :account_id, rr.feature_key, rr.payload, CURRENT_TIMESTAMP()FROM AI_FEATURE_HUB.RATE_RULES rrWHERE rr.effective_from &lt;= :as_of AND (rr.effective_to IS NULL OR rr.effective_to &gt;= :as_of);RETURN &#39;OK&#39;;$$;

Purpose: Ingest staged usage JSONL

FROM EMBEDDINGS_STAGE OR USAGE_EVENTS_STAGE INTO TENANT_FEATURE_USAGE with idempotent MERGE.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.INGEST_USAGE_FROM_STAGE (stage_path STRING)RETURNS VARIANTLANGUAGE SQLAS $$COPY INTO AI_FEATURE_HUB.USAGE_EVENTS_RAWFROM @:stage_pathFILE_FORMAT = (TYPE = &#39;JSON&#39;)ON_ERROR = &#39;CONTINUE&#39;;MERGE INTO AI_FEATURE_HUB.TENANT_FEATURE_USAGE tgtUSING (  SELECT value:usage_id::STRING AS usage_id, value:account_id::STRING AS account_id, value:feature_key::STRING AS feature_key, value:usage_amount::NUMBER AS usage_amount, value:usage_ts::TIMESTAMP_LTZ AS usage_ts, value:meta AS meta  FROM AI_FEATURE_HUB.USAGE_EVENTS_RAW) srcON tgt.usage_id = src.usage_idWHEN MATCHED THEN UPDATE SET usage_amount = src.usage_amount, usage_ts = src.usage_ts, meta = src.meta, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT (usage_id, account_id, feature_key, usage_amount, usage_ts, meta, created_at)VALUES (src.usage_id, src.account_id, src.feature_key, src.usage_amount, src.usage_ts, src.meta, CURRENT_TIMESTAMP());RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;OK&#39;,&#39;ingested_at&#39;,CURRENT_TIMESTAMP());$$;

Purpose: Ingest embeddings JSONL INTO DOCUMENT_EMBEDDINGS table with provenance capture (external_id, model_id, vector, metadata).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.INGEST_EMBEDDINGS_FROM_STAGE (stage_path STRING)RETURNS VARIANTLANGUAGE SQLAS $$COPY INTO AI_FEATURE_HUB.EMBEDDINGS_STAGE FROM @:stage_path FILE_FORMAT=(TYPE=&#39;JSON&#39;) ON_ERROR=&#39;CONTINUE&#39;;INSERT INTO AI_FEATURE_HUB.DOCUMENT_EMBEDDINGS(doc_id, external_id, model_id, embedding, metadata, created_at)SELECT GENERATE_UUID(), value:external_id::STRING, value:model_id::STRING, value:vector::ARRAY, value:metadata, CURRENT_TIMESTAMP()FROM AI_FEATURE_HUB.EMBEDDINGS_STAGE;RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;OK&#39;,&#39;rows&#39;,(SELECT COUNT(*) FROM AI_FEATURE_HUB.EMBEDDINGS_STAGE));$$;

Purpose: Wrapper to
CALL similarity External Function (OR fallback to native VECTOR cosine)that
RETURNS top-k results.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.QUERY_SIMILARITY (vector ARRAY, k INT, model_id STRING)RETURNS VARIANTLANGUAGE SQLAS $$-- Prefer native VECTOR functionality if present otherwise call registered External FunctionBEGIN  IF (SELECT COUNT(*) FROM INFORMATION_SCHEMA.FUNCTIONS WHERE FUNCTION_NAME ILIKE &#39;ANN_SIMILARITY_FN&#39;) &gt; 0 THEN RETURN (SELECT ANN_SIMILARITY_FN(:vector, :k, :model_id));  ELSE RETURN (SELECT ARRAY_AGG(OBJECT_CONSTRUCT(&#39;doc_id&#39;,d.doc_id,&#39;score&#39;,COS_SIM(d.embedding,:vector)) ORDER BY COS_SIM(d.embedding,:vector) DESC LIMIT :k) FROM AI_FEATURE_HUB.DOCUMENT_EMBEDDINGS d WHERE d.model_id = :model_id);  END IF;END;$$;

