CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.REGISTER_EXTERNAL_FUNCTION_RECORD (fn_name STRING, integration_name STRING, endpoint STRING, config VARIANT, created_by STRING)RETURNS STRINGLANGUAGE SQLAS $$MERGE INTO AI_FEATURE_HUB.EXTERNAL_FUNCTIONS tgtUSING (SELECT :fn_name AS fn_name) src ON tgt.fn_name = src.fn_nameWHEN MATCHED THEN UPDATE SET integration_name = :integration_name, endpoint = :endpoint, config = :config, updated_by = :created_by, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT (fn_id, fn_name, integration_name, endpoint, config, created_by, created_at)VALUES (GENERATE_UUID(), :fn_name, :integration_name, :endpoint, :config, :created_by, CURRENT_TIMESTAMP());RETURN :fn_name;$$;

