CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.RESUME_DEPLOY_TASKS (task_prefix STRING)RETURNS VARIANTLANGUAGE SQLAS $$DECLARE  c CURSOR FOR SELECT TASK_NAME FROM INFORMATION_SCHEMA.TASKS WHERE TASK_NAME LIKE :task_prefix || &#39;%&#39;;  t STRING;BEGIN  FOR rec IN c DOEXECUTE IMMEDIATE &#39;ALTER TASK &#39; || rec.TASK_NAME || &#39; RESUME&#39;;  END FOR;  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;RESUMED&#39;,&#39;prefix&#39;,:task_prefix,&#39;resumed_at&#39;,CURRENT_TIMESTAMP());END;$$;

