CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.GENERATE_INVOICE_PDF_LINK (invoice_id STRING, run_id STRING, account_id STRING, generated_by STRING)RETURNS STRINGLANGUAGE SQLAS $$INSERT INTO AI_FEATURE_HUB.INVOICE_PDFS(pdf_id, invoice_id, run_id, account_id, pdf_url, created_by, created_at)VALUES(GENERATE_UUID(), :invoice_id, :run_id, :account_id, &#39;https://pdf.service/internal/&#39; || :invoice_id, :generated_by, CURRENT_TIMESTAMP());RETURN (SELECT pdf_url FROM AI_FEATURE_HUB.INVOICE_PDFS WHERE invoice_id = :invoice_id LIMIT 1);$$;

