CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.ARCHIVE_OLD_BILLING_RUNS (retention_days INT)RETURNS VARIANTLANGUAGE SQLAS $$INSERT INTO AI_FEATURE_HUB.BILLING_RUN_ARCHIVE SELECT * FROM AI_FEATURE_HUB.BILLING_RUN WHERE created_at &lt; DATEADD(day, -:retention_days, CURRENT_TIMESTAMP());DELETE FROM AI_FEATURE_HUB.BILLING_RUN WHERE created_at &lt; DATEADD(day, -:retention_days, CURRENT_TIMESTAMP());RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;ARCHIVED&#39;,&#39;retention_days&#39;,:retention_days,&#39;archived_at&#39;,CURRENT_TIMESTAMP());$$;

