CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.COMPUTE_SLO_SUMMARY (as_of_date DATE)RETURNS VARIANTLANGUAGE SQLAS $$RETURN (SELECT OBJECT_AGG(model_key, OBJECT_CONSTRUCT(&#39;p95&#39;,APPROX_PERCENTILE(duration,0.95),&#39;p99&#39;,APPROX_PERCENTILE(duration,0.99))) FROM (SELECT model_key, DATEDIFF(&#39;ms&#39;, request_ts, response_ts) AS duration FROM AI_FEATURE_HUB.INFERENCE_PROVENANCE WHERE request_ts::DATE = :as_of_date));$$;

