CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.LOAD_FAISS_SHARD (shard_id STRING, snapshot_id STRING, shard_uri STRING, shard_size INT)RETURNS STRINGLANGUAGE SQLAS $$MERGE INTO AI_FEATURE_HUB.FAISS_SHARD_COORDINATOR tgtUSING (SELECT :shard_id AS shard_id) src ON tgt.shard_id = src.shard_idWHEN MATCHED THEN UPDATE SET snapshot_id = :snapshot_id, shard_uri = :shard_uri, shard_size = :shard_size, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT(shard_id, snapshot_id, shard_uri, shard_size, created_at) VALUES (:shard_id, :snapshot_id, :shard_uri, :shard_size, CURRENT_TIMESTAMP());RETURN :shard_id;$$;

