CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.RUN_QA_SMOKE (test_run_id STRING, env_tag STRING)RETURNS VARIANTLANGUAGE SQLAS $$INSERT INTO AI_FEATURE_HUB.QA_RUNS(test_run_id, env_tag, status, started_at)VALUES(:test_run_id, :env_tag, &#39;RUNNING&#39;, CURRENT_TIMESTAMP());-- sample check: ensure at least one embedding existsSELECT CASE WHEN COUNT(*) = 0 THEN &#39;FAIL&#39; ELSE &#39;PASS&#39; END AS check_result INTO :_res FROM AI_FEATURE_HUB.DOCUMENT_EMBEDDINGS;UPDATE AI_FEATURE_HUB.QA_RUNS SET status = CASE WHEN :_res=&#39;PASS&#39; THEN &#39;PASS&#39; ELSE &#39;FAIL&#39; END, finished_at = CURRENT_TIMESTAMP() WHERE test_run_id = :test_run_id;RETURN OBJECT_CONSTRUCT(&#39;test_run_id&#39;,:test_run_id,&#39;result&#39;,:_res);$$;

