PROC_FEATURE_INSTANCE_METRIC_AGGREGATE — Purpose: aggregate recent raw metrics INTO hourly rollups FOR a feature instance FOR telemetry AND billing attribution.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_METRIC_AGGREGATE (p_window_start TIMESTAMP_LTZ, p_window_end TIMESTAMP_LTZ)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  INSERT INTO AI_FEATURE_HUB.feature_instance_metric_hourly_rollup(instance_ref, feature_key, org_id, metric_name, metric_hour, sum_value, avg_value, min_value, max_value, samples, created_at)  SELECT instance_ref, feature_key, org_id, metric_name, DATE_TRUNC(&#39;hour&#39;, recorded_at) AS metric_hour, SUM(metric_value) AS sum_value, AVG(metric_value) AS avg_value, MIN(metric_value) AS min_value, MAX(metric_value) AS max_value, COUNT(*) AS samples, CURRENT_TIMESTAMP()

  FROM AI_FEATURE_HUB.feature_instance_metric_collection_logs  WHERE recorded_at &gt;= p_window_start AND recorded_at &lt; p_window_end  GROUP BY instance_ref, feature_key, org_id, metric_name, DATE_TRUNC(&#39;hour&#39;, recorded_at)  ;  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;OK&#39;,&#39;inserted_rows&#39;, (SELECT COUNT(*) FROM AI_FEATURE_HUB.feature_instance_metric_hourly_rollup WHERE metric_hour &gt;= DATE_TRUNC(&#39;hour&#39;, p_window_start) AND metric_hour &lt; DATE_TRUNC(&#39;hour&#39;, p_window_end)));END;$$;

PROC_FEATURE_INSTANCE_ALERT_HISTORY_PRUNE — Purpose: prune old alert history rows according to org retention policy AND record audit of prune action.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_ALERT_HISTORY_PRUNE (p_org_id STRING, p_older_than_days INT)RETURNS VARIANTLANGUAGE SQLAS $$DECLARE deleted_count NUMBER := 0;BEGIN  deleted_count := (SELECT COUNT(*) FROM AI_FEATURE_HUB.feature_instance_alert_history WHERE org_id = p_org_id AND raised_at &lt; DATEADD(day, -p_older_than_days, CURRENT_TIMESTAMP()));  DELETE FROM AI_FEATURE_HUB.feature_instance_alert_history WHERE org_id = p_org_id AND raised_at &lt; DATEADD(day, -p_older_than_days, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.retention_audit(audit_id, org_id, artifact_type, artifact_name, action, details, created_at)  VALUES (UUID_STRING(), p_org_id, &#39;ALERT_HISTORY&#39;, &#39;feature_instance_alert_history&#39;, &#39;PRUNE&#39;, OBJECT_CONSTRUCT(&#39;deleted_count&#39;, deleted_count, &#39;older_than_days&#39;, p_older_than_days), CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;OK&#39;,&#39;deleted_count&#39;,deleted_count);END;$$;

