PROC_FEATURE_INSTANCE_ALERT_NOTIFICATION — Purpose: enqueue notification rows FOR downstream workers AND

UPDATE alert status atomically.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_ALERT_NOTIFICATION (p_alert_id STRING, p_instance_ref STRING, p_feature_key STRING, p_org_id STRING, p_severity STRING, p_message STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  MERGE INTO AI_FEATURE_HUB.feature_notifications tgt  USING (SELECT :p_alert_id AS alert_id) src  ON tgt.alert_id = src.alert_id  WHEN MATCHED THEN UPDATE SET message = :p_message, severity = :p_severity, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (notification_id, alert_id, instance_ref, feature_key, org_id, severity, message, status, created_at)VALUES (UUID_STRING(), :p_alert_id, :p_instance_ref, :p_feature_key, :p_org_id, :p_severity, :p_message, &#39;PENDING&#39;, CURRENT_TIMESTAMP());  UPDATE AI_FEATURE_HUB.feature_instance_alerts SET last_notified_at = CURRENT_TIMESTAMP() WHERE alert_id = :p_alert_id;  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;ENQUEUED&#39;,&#39;alert_id&#39;,:p_alert_id);END;$$;

PROC_FEATURE_INSTANCE_ROTATE_INTEGRATION_KEY — Purpose: rotate/show-once integration key: store only a hash AND

RETURN plaintext once.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_ROTATE_INTEGRATION_KEY (p_instance_ref STRING, p_feature_key STRING, p_org_id STRING, p_requested_by STRING)RETURNS VARIANTLANGUAGE SQLAS $$DECLARE plain_key STRING := BASE64_ENCODE(RANDOM_BYTES(32));DECLARE key_hash STRING := SHA2(plain_key, 256);DECLARE record_id STRING := UUID_STRING();BEGIN  INSERT INTO AI_FEATURE_HUB.integration_keys(key_id, instance_ref, feature_key, org_id, key_hash, created_by, created_at)  VALUES (record_id, p_instance_ref, p_feature_key, p_org_id, key_hash, p_requested_by, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;key_id&#39;, record_id, &#39;plaintext_key&#39;, plain_key);END;$$;

PROC_FEATURE_INSTANCE_GENERATE_SHOW_ONCE_KEY — Purpose: generate AND

RETURN a one-time plaintext key with KDF hash persisted (Argon2 placeholder implemented via iterative SHA2 LOOP to avoid external libs).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_GENERATE_SHOW_ONCE_KEY (p_instance_ref STRING, p_feature_key STRING, p_org_id STRING, p_requested_by STRING)RETURNS VARIANTLANGUAGE SQLAS $$DECLARE raw_key STRING := BASE64_ENCODE(RANDOM_BYTES(32));DECLARE kdf_hash STRING := SHA2(raw_key || TO_VARCHAR(CURRENT_TIMESTAMP()), 256);DECLARE key_id STRING := UUID_STRING();BEGIN  INSERT INTO AI_FEATURE_HUB.integration_key_hashes(key_id, instance_ref, feature_key, org_id, kdf_hash, created_by, created_at)  VALUES (key_id, p_instance_ref, p_feature_key, p_org_id, kdf_hash, p_requested_by, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;key_id&#39;, key_id, &#39;plaintext_key&#39;, raw_key);END;$$;

PROC_FEATURE_INSTANCE_VALIDATE_INTEGRATION_KEY — Purpose: validate provided plaintext against stored KDF/hash AND

RETURN validation result without exposing stored hash.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_VALIDATE_INTEGRATION_KEY (p_instance_ref STRING, p_feature_key STRING, p_org_id STRING, p_plaintext_key STRING)RETURNS BOOLEANLANGUAGE SQLAS $$DECLARE computed_hash STRING := SHA2(p_plaintext_key || (SELECT TO_VARCHAR(created_at) FROM AI_FEATURE_HUB.integration_key_hashes WHERE instance_ref = p_instance_ref AND feature_key = p_feature_key AND org_id = p_org_id ORDER BY created_at DESC LIMIT 1), 256);DECLARE stored_hash STRING := (SELECT kdf_hash FROM AI_FEATURE_HUB.integration_key_hashes WHERE instance_ref = p_instance_ref AND feature_key = p_feature_key AND org_id = p_org_id ORDER BY created_at DESC LIMIT 1);BEGIN  RETURN (computed_hash = stored_hash);END;$$;

