CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_SETTLE_BILLING_ADJUSTMENT (p_adjustment_id STRING, p_account_id STRING, p_instance_ref STRING, p_feature_key STRING, p_amount NUMBER, p_reason STRING, p_created_by STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  INSERT INTO AI_FEATURE_HUB.billing_adjustments(adjustment_id, account_id, instance_ref, feature_key, amount, reason, created_by, created_at, status)  VALUES (p_adjustment_id, p_account_id, p_instance_ref, p_feature_key, p_amount, p_reason, p_created_by, CURRENT_TIMESTAMP(), &#39;APPLIED&#39;);  INSERT INTO AI_FEATURE_HUB.usage_events(event_id, account_id, feature_key, usage_qty, event_ts, source, created_at)  VALUES (UUID_STRING(), p_account_id, p_feature_key, -ABS(p_amount), CURRENT_TIMESTAMP(), &#39;ADMIN_ADJUSTMENT&#39;, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;APPLIED&#39;,&#39;adjustment_id&#39;,p_adjustment_id);END;$$;

