CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_EXPORT_EVIDENCE_BUNDLE (p_bundle_id STRING, p_requested_by STRING)RETURNS VARIANTLANGUAGE SQLAS $$DECLARE export_token STRING := BASE64_ENCODE(CONCAT(p_bundle_id, &#39;:&#39;, TO_VARCHAR(CURRENT_TIMESTAMP()), &#39;:&#39;, UUID_STRING()));BEGIN  UPDATE AI_FEATURE_HUB.evidence_bundles SET exported_at = CURRENT_TIMESTAMP(), exported_by = p_requested_by WHERE bundle_id = p_bundle_id;  INSERT INTO AI_FEATURE_HUB.evidence_export_audit(audit_id, bundle_id, requested_by, token, created_at)  VALUES (UUID_STRING(), p_bundle_id, p_requested_by, export_token, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;bundle_id&#39;, p_bundle_id, &#39;export_token&#39;, export_token);END;$$;

PROC_FEATURE_INSTANCE_CREATE_USAGE_EVENT — Purpose: canonical single-row insertion helper that enforces idempotency key uniqueness AND
RETURNS event id.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_CREATE_USAGE_EVENT (p_event_id STRING, p_account_id STRING, p_feature_key STRING, p_usage_qty NUMBER, p_idempotency_key STRING, p_payload VARIANT)RETURNS STRINGLANGUAGE SQLAS $$BEGIN  MERGE INTO AI_FEATURE_HUB.usage_events tgt  USING (SELECT :p_idempotency_key AS idempotency_key) src  ON tgt.idempotency_key = src.idempotency_key  WHEN MATCHED THEN UPDATE SET event_ts = CURRENT_TIMESTAMP(), usage_qty = :p_usage_qty, payload = :p_payload, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (event_id, account_id, feature_key, usage_qty, idempotency_key, event_ts, payload, created_at)VALUES (:p_event_id, :p_account_id, :p_feature_key, :p_usage_qty, :p_idempotency_key, CURRENT_TIMESTAMP(), :p_payload, CURRENT_TIMESTAMP());  RETURN :p_event_id;END;$$;

PROC_FEATURE_INSTANCE_MERGE_USAGE_FROM_STAGING — Purpose: idempotent MERGE

FROM staging table STAGED_USAGE INTO TENANT_FEATURE_USAGE with audit.

