;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FEATURE_INSTANCE_MERGE_USAGE_FROM_STAGING (p_batch_id STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  MERGE INTO AI_FEATURE_HUB.tenant_feature_usage tgt  USING (SELECT event_id, account_id, feature_key, usage_qty, idempotency_key, event_ts, raw_payload FROM AI_FEATURE_HUB.staged_usage WHERE batch_id = p_batch_id) src  ON tgt.idempotency_key = src.idempotency_key  WHEN MATCHED THEN UPDATE SET usage_qty = src.usage_qty, event_ts = src.event_ts, raw_payload = src.raw_payload, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (usage_id, account_id, feature_key, usage_qty, idempotency_key, event_ts, raw_payload, created_at)VALUES (UUID_STRING(), src.account_id, src.feature_key, src.usage_qty, src.idempotency_key, src.event_ts, src.raw_payload, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.ingest_audit(audit_id, batch_id, records_processed, processed_at) VALUES (UUID_STRING(), p_batch_id, (SELECT COUNT(*) FROM AI_FEATURE_HUB.staged_usage WHERE batch_id = p_batch_id), CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;MERGED&#39;,&#39;batch_id&#39;,p_batch_id);END;$$;

PROC_DOCUMENT_EMBEDDING_MERGE — Purpose: idempotent

MERGE INTO DOCUMENT_EMBEDDINGS

FROM STAGED_EMBEDDINGS with provenance link.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_DOCUMENT_EMBEDDING_MERGE (p_batch_id STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  MERGE INTO AI_FEATURE_HUB.document_embeddings tgt  USING (SELECT doc_id, embedding, idempotency_key, provenance_id, metadata FROM AI_FEATURE_HUB.staged_embeddings WHERE batch_id = p_batch_id) src  ON tgt.idempotency_key = src.idempotency_key  WHEN MATCHED THEN UPDATE SET embedding = src.embedding, provenance_id = src.provenance_id, metadata = src.metadata, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (embedding_id, doc_id, embedding, idempotency_key, provenance_id, metadata, created_at)VALUES (UUID_STRING(), src.doc_id, src.embedding, src.idempotency_key, src.provenance_id, src.metadata, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.embedding_ingest_audit(audit_id, batch_id, rows, created_at) VALUES (UUID_STRING(), p_batch_id, (SELECT COUNT(*) FROM AI_FEATURE_HUB.staged_embeddings WHERE batch_id = p_batch_id), CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;EMBEDDINGS_MERGED&#39;,&#39;batch_id&#39;,p_batch_id);END;$$;

PROC_FAISS_SNAPSHOT_REGISTER — Purpose: register a new FAISS snapshot manifest row AND schedule container build.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FAISS_SNAPSHOT_REGISTER (p_snapshot_id STRING, p_index_prefix STRING, p_org_id STRING, p_created_by STRING, p_metadata VARIANT)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  INSERT INTO AI_FEATURE_HUB.faiss_snapshots(snapshot_id, index_prefix, org_id, metadata, status, created_by, created_at)  VALUES (p_snapshot_id, p_index_prefix, p_org_id, p_metadata, &#39;REGISTERED&#39;, p_created_by, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.faiss_build_queue(queue_id, snapshot_id, status, enqueued_at) VALUES (UUID_STRING(), p_snapshot_id, &#39;PENDING&#39;, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;REGISTERED&#39;,&#39;snapshot_id&#39;,p_snapshot_id);END;$$;

PROC_FAISS_SNAPSHOT_RETIRE — Purpose: mark snapshot retire requested AND enqueue audit; does NOT DELETE external objects.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_FAISS_SNAPSHOT_RETIRE (p_snapshot_id STRING, p_requested_by STRING, p_reason STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  UPDATE AI_FEATURE_HUB.faiss_snapshots SET status = &#39;RETIRED_REQUESTED&#39;, retired_by = p_requested_by, retired_reason = p_reason, retired_at = CURRENT_TIMESTAMP() WHERE snapshot_id = p_snapshot_id;  INSERT INTO AI_FEATURE_HUB.faiss_retirement_audit(audit_id, snapshot_id, requested_by, reason, requested_at) VALUES (UUID_STRING(), p_snapshot_id, p_requested_by, p_reason, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;RETIRE_REQUESTED&#39;,&#39;snapshot_id&#39;,p_snapshot_id);END;$$;

PROC_EXTERNAL_FUNCTION_REGISTER — Purpose: CREATE API_INTEGRATION AND EXTERNAL FUNCTION registration rows in a registration table AND

RETURN suggested registration SQL snippet in a VARIANT.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_EXTERNAL_FUNCTION_REGISTER (p_integration_id STRING, p_provider STRING, p_api_host STRING, p_iam_arn STRING, p_allowed_prefixes ARRAY, p_created_by STRING)RETURNS VARIANTLANGUAGE SQLAS $$DECLARE reg_sql STRING;BEGIN  INSERT INTO AI_FEATURE_HUB.external_function_registry(integration_id, provider, api_host, iam_arn, allowed_prefixes, created_by, created_at)  VALUES (p_integration_id, p_provider, p_api_host, p_iam_arn, p_allowed_prefixes, p_created_by, CURRENT_TIMESTAMP());  reg_sql := &#39;CREATE OR REPLACE API_INTEGRATION &#39; || QUOTE_IDENT(&#39;API_INTEGRATION_&#39; || p_integration_id) || &#39; TYPE = EXTERNAL_OAUTH ENABLED = TRUE&#39;;  RETURN OBJECT_CONSTRUCT(&#39;integration_id&#39;, p_integration_id, &#39;suggested_sql&#39;, reg_sql);END;$$;

PROC_EXTERNAL_FUNCTION_TEST_PING — Purpose: record a ping attempt to an External Function endpoint AND

RETURN last-known status.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_EXTERNAL_FUNCTION_TEST_PING (p_integration_id STRING, p_request_id STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  INSERT INTO AI_FEATURE_HUB.external_function_ping_log(ping_id, integration_id, request_id, pinged_at)  VALUES (UUID_STRING(), p_integration_id, p_request_id, CURRENT_TIMESTAMP());  RETURN (SELECT OBJECT_CONSTRUCT(&#39;integration_id&#39;, integration_id, &#39;last_ping&#39;, MAX(pinged_at)) FROM AI_FEATURE_HUB.external_function_ping_log WHERE integration_id = p_integration_id);END;$$;

PROC_TASK_SCHEDULE_RUN_BILLING — Purpose: idempotent CREATE/alter of TASK that schedules billing run with safe resume semantics.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_TASK_SCHEDULE_RUN_BILLING (p_task_name STRING, p_cron_schedule STRING, p_warehouse STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  EXECUTE IMMEDIATE &#39;CREATE OR REPLACE TASK &#39; || p_task_name || &#39; WAREHOUSE = &#39; || p_warehouse || &#39; SCHEDULE = &#39;&#39;&#39; || p_cron_schedule || &#39;&#39;&#39; WHEN SYSTEM$STREAM_HAS_DATA(false) = true AS CALL AI_FEATURE_HUB.RUN_BILLING_RUN(CURRENT_TIMESTAMP()::STRING, CURRENT_TIMESTAMP()::STRING, NULL, TRUE);&#39;;  RETURN OBJECT_CONSTRUCT(&#39;task&#39;, p_task_name, &#39;schedule&#39;, p_cron_schedule);END;$$;

PROC_TASK_SCHEDULE_EMBEDDING_INGEST — Purpose: idempotent CREATE/alter of TASK to run embedding ingest

FROM staging periodically.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_TASK_SCHEDULE_EMBEDDING_INGEST (p_task_name STRING, p_cron_schedule STRING, p_warehouse STRING)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  EXECUTE IMMEDIATE &#39;CREATE OR REPLACE TASK &#39; || p_task_name || &#39; WAREHOUSE = &#39; || p_warehouse || &#39; SCHEDULE = &#39;&#39;&#39; || p_cron_schedule || &#39;&#39;&#39; AS CALL AI_FEATURE_HUB.PROC_DOCUMENT_EMBEDDING_MERGE(&#39;&#39;&#39; || UUID_STRING() || &#39;&#39;&#39;);&#39;;  RETURN OBJECT_CONSTRUCT(&#39;task&#39;, p_task_name, &#39;schedule&#39;, p_cron_schedule);END;$$;

PROC_TELEMETRY_SUMMARY_ROLLUP — Purpose: roll up telemetry (model telemetry + task success/failure counts)INTO a daily summary table FOR SLO reporting.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_TELEMETRY_SUMMARY_ROLLUP (p_date DATE)RETURNS VARIANTLANGUAGE SQLAS $$BEGIN  INSERT INTO AI_FEATURE_HUB.telemetry_daily_summary(summary_date, org_id, models_trained, model_calls, failed_tasks, successful_tasks, created_at)  SELECT p_date AS summary_date, org_id, SUM(CASE WHEN event_type = &#39;MODEL_TRAIN&#39; THEN 1 ELSE 0 END) AS models_trained, SUM(CASE WHEN event_type = &#39;MODEL_CALL&#39; THEN 1 ELSE 0 END) AS model_calls, SUM(CASE WHEN task_status = &#39;FAILED&#39; THEN 1 ELSE 0 END) AS failed_tasks, SUM(CASE WHEN task_status = &#39;SUCCESS&#39; THEN 1 ELSE 0 END) AS successful_tasks, CURRENT_TIMESTAMP()

FROM (    SELECT org_id, &#39;MODEL_TRAIN&#39; AS event_type, NULL AS task_status FROM AI_FEATURE_HUB.model_telemetry WHERE DATE_TRUNC(&#39;day&#39;, created_at) = p_date    UNION ALL    SELECT org_id, &#39;MODEL_CALL&#39; AS event_type, NULL AS task_status FROM AI_FEATURE_HUB.model_call_logs WHERE DATE_TRUNC(&#39;day&#39;, called_at) = p_date    UNION ALL    SELECT org_id, NULL AS event_type, task_status FROM AI_FEATURE_HUB.task_runs WHERE DATE_TRUNC(&#39;day&#39;, run_at) = p_date  )  GROUP BY org_id;  RETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;ROLLED_UP&#39;,&#39;summary_date&#39;,p_date);END;$$;

AI_FEATURE_HUB.PROC_PERSIST_BILLING_RUNS — Purpose: persist a billing_run AND its billing_line_items atomically after a preview run (idempotent; IF run_id exists, updates run metadata AND
RETURNS existing run_id).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_PERSIST_BILLING_RUNS (p_run_id STRING, p_account_id STRING, p_run_ts TIMESTAMP_LTZ, p_lines VARIANT, p_total_amount NUMBER, p_status STRING)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE existing_count NUMBER := 0;BEGIN  SELECT COUNT(*) INTO :existing_count FROM AI_FEATURE_HUB.billing_runs WHERE run_id = p_run_id;  IF existing_count = 0 THENINSERT INTO AI_FEATURE_HUB.billing_runs(run_id, account_id, run_ts, total_amount, status, created_at)VALUES (p_run_id, p_account_id, p_run_ts, p_total_amount, p_status, CURRENT_TIMESTAMP());-- p_lines expected as ARRAY of OBJECTs with keys: line_id, product_code, qty, unit_price, line_total, metadataFOR rec IN (SELECT VALUE FROM TABLE(FLATTEN(INPUT =&gt; p_lines))) DO INSERT INTO AI_FEATURE_HUB.billing_line_items(line_id, run_id, account_id, product_code, qty, unit_price, line_total, metadata, created_at) VALUES (rec.value:line_id::STRING, p_run_id, p_account_id, rec.value:product_code::STRING, rec.value:qty::NUMBER, rec.value:unit_price::NUMBER, rec.value:line_total::NUMBER, rec.value:metadata::VARIANT, CURRENT_TIMESTAMP());END FOR;  ELSEUPDATE AI_FEATURE_HUB.billing_runs SET total_amount = p_total_amount, status = p_status, updated_at = CURRENT_TIMESTAMP() WHERE run_id = p_run_id;  END IF;  RETURN OBJECT_CONSTRUCT(&#39;run_id&#39;, p_run_id, &#39;persisted&#39;, IFF(existing_count=0, TRUE, FALSE));END;$$;This PROCEDURE implements the Snowflake-authoritative billing persist pattern AND idempotent write semantics described in the billing/runbook artifacts.

AI_FEATURE_HUB.PROC_RECONCILE_BILLING_VS_USAGE — Purpose: reconcile billing_line_items to tenant_feature_usage, report mismatches AND CREATE reconciliation_audit rows.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_RECONCILE_BILLING_VS_USAGE (p_run_id STRING)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE mismatch_count NUMBER := 0;BEGIN  INSERT INTO AI_FEATURE_HUB.reconciliation_audit(audit_id, run_id, created_at)  VALUES (UUID_STRING(), p_run_id, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.reconciliation_mismatches(mismatch_id, run_id, account_id, product_code, billed_qty, usage_qty, detected_at)  SELECT UUID_STRING(), bli.run_id, bli.account_id, bli.product_code,SUM(bli.qty) AS billed_qty,COALESCE(SUM(tfu.usage_qty),0) AS usage_qty,CURRENT_TIMESTAMP()


  FROM AI_FEATURE_HUB.billing_line_items bli  LEFT JOIN AI_FEATURE_HUB.tenant_feature_usage tfu    ON tfu.account_id = bli.account_id AND tfu.feature_key = bli.product_code  WHERE bli.run_id = p_run_id  GROUP BY bli.run_id, bli.account_id, bli.product_code  HAVING COALESCE(SUM(bli.qty),0) &lt;&gt; COALESCE(SUM(tfu.usage_qty),0);  SELECT COUNT(*) INTO :mismatch_count FROM AI_FEATURE_HUB.reconciliation_mismatches WHERE run_id = p_run_id;  UPDATE AI_FEATURE_HUB.reconciliation_audit SET mismatches = mismatch_count, completed_at = CURRENT_TIMESTAMP() WHERE run_id = p_run_id;  RETURN OBJECT_CONSTRUCT(&#39;run_id&#39;, p_run_id, &#39;mismatch_count&#39;, mismatch_count);END;$$;This PROCEDURE follows the reconciliation AND audit patterns AND writes mismatch evidence FOR billing QA
AS described in the docs.

AI_FEATURE_HUB.PROC_RATE_RULES_STAGE_INSERT — Purpose: INSERT a rate rule change INTO RATE_RULES_STAGING FOR approval (staging + show metadata).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_RATE_RULES_STAGE_INSERT (p_request_id STRING, p_org_id STRING, p_actor STRING, p_rule_variant VARIANT)RETURNS STRINGLANGUAGE SQLAS$$BEGIN  INSERT INTO AI_FEATURE_HUB.rate_rules_staging(request_id, org_id, actor, rule_payload, status, requested_at)  VALUES (p_request_id, p_org_id, p_actor, p_rule_variant, &#39;PENDING&#39;, CURRENT_TIMESTAMP());  RETURN p_request_id;END;$$;This implements the staging pattern recommended FOR admin edits to ensure changes require explicit approval before activation.

AI_FEATURE_HUB.PROC_APPROVE_RATE_RULE — Purpose: approve a staged rate rule AND, ON approval, upsert INTO RATE_RULES AND record audit.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_APPROVE_RATE_RULE (p_request_id STRING, p_approver STRING)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE staged VARIANT;BEGIN  SELECT rule_payload INTO :staged FROM AI_FEATURE_HUB.rate_rules_staging WHERE request_id = p_request_id AND status = &#39;PENDING&#39; FOR UPDATE;  IF staged IS NULL THENRETURN OBJECT_CONSTRUCT(&#39;status&#39;,&#39;NOT_FOUND&#39;);  END IF;  MERGE INTO AI_FEATURE_HUB.rate_rules tgt  USING (SELECT staged:rule_id::STRING AS rule_id, staged AS payload) src  ON tgt.rule_id = src.rule_id  WHEN MATCHED THEN UPDATE SET active = TRUE, rule_definition = src.payload, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (rule_id, rule_definition, active, created_at) VALUES (src.rule_id, src.payload, TRUE, CURRENT_TIMESTAMP());  UPDATE AI_FEATURE_HUB.rate_rules_staging SET status = &#39;APPROVED&#39;, reviewed_by = p_approver, reviewed_at = CURRENT_TIMESTAMP() WHERE request_id = p_request_id;  INSERT INTO AI_FEATURE_HUB.rate_rules_audit(audit_id, request_id, action, performed_by, performed_at, details)  VALUES (UUID_STRING(), p_request_id, &#39;APPROVE&#39;, p_approver, CURRENT_TIMESTAMP(), staged);  RETURN OBJECT_CONSTRUCT(&#39;request_id&#39;, p_request_id, &#39;approved&#39;, TRUE);END;$$;This implements the recommended approve/promote workflow (staging → approve → active)referenced in the admin UI design.

AI_FEATURE_HUB.PROC_PROMOTE_RATE_RULES_BATCH — Purpose: atomically promote multiple approved staging rows to active rules (batch apply)AND emit migration audit.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_PROMOTE_RATE_RULES_BATCH (p_request_ids ARRAY, p_migrated_by STRING)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE migrated_count NUMBER := 0;BEGIN  FOR r IN (SELECT VALUE FROM TABLE(FLATTEN(INPUT =&gt; p_request_ids))) DOCALL AI_FEATURE_HUB.PROC_APPROVE_RATE_RULE(r.value::STRING, p_migrated_by);migrated_count := migrated_count + 1;  END FOR;  INSERT INTO AI_FEATURE_HUB.rate_rules_migration_log(migration_id, migrated_by, migrated_at, count)  VALUES (UUID_STRING(), p_migrated_by, CURRENT_TIMESTAMP(), migrated_count);  RETURN OBJECT_CONSTRUCT(&#39;migrated_count&#39;, migrated_count);END;$$;This batch promotion aligns with staging+approval practices FOR safe admin rollouts.

AI_FEATURE_HUB.PROC_UPSERT_RATE_RULE_TEMPLATE — Purpose: upsert a reusable RATE_RULE_TEMPLATE AND record versioning.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_UPSERT_RATE_RULE_TEMPLATE (p_template_id STRING, p_org_id STRING, p_name STRING, p_template_def VARIANT, p_updated_by STRING)RETURNS VARIANTLANGUAGE SQLAS$$BEGIN  MERGE INTO AI_FEATURE_HUB.rate_rule_templates tgt  USING (SELECT :p_template_id AS template_id) src ON tgt.template_id = src.template_id  WHEN MATCHED THEN UPDATE SET name = :p_name, template_definition = :p_template_def, updated_by = :p_updated_by, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (template_id, org_id, name, template_definition, created_by, created_at) VALUES (:p_template_id, :p_org_id, :p_name, :p_template_def, :p_updated_by, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.rate_rule_template_versions(version_id, template_id, template_snapshot, created_by, created_at)  VALUES (UUID_STRING(), p_template_id, p_template_def, p_updated_by, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;template_id&#39;, p_template_id);END;$$;This implements template versioning FOR rate rules
AS recommended FOR auditable billing changes.

AI_FEATURE_HUB.PROC_APPLY_RATE_RULES_TO_USAGE — Purpose: given a date window, compute applied rate lines per usage row

USING active RATE_RULES AND write provisional billing_line_items (preview mode).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_APPLY_RATE_RULES_TO_USAGE (p_window_start TIMESTAMP_LTZ, p_window_end TIMESTAMP_LTZ, p_preview_run_id STRING)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE inserted NUMBER := 0;BEGIN  FOR u IN (SELECT * FROM AI_FEATURE_HUB.tenant_feature_usage WHERE event_ts &gt;= p_window_start AND event_ts &lt; p_window_end) DO-- Find active rule for feature_key (simplified: first match)LET rule VARIANT := (SELECT rule_definition FROM AI_FEATURE_HUB.rate_rules WHERE active = TRUE AND ARRAY_CONTAINS(TO_VARIANT(TO_JSON(RTMP =&gt; rule_definition):feature_keys::ARRAY), u.feature_key) LIMIT 1);LET unit_price NUMBER := IFF(rule IS NULL, 0.0, COALESCE(rule:default_unit_price::NUMBER,0.0));LET line_id STRING := UUID_STRING();INSERT INTO AI_FEATURE_HUB.billing_line_items(line_id, run_id, account_id, product_code, qty, unit_price, line_total, metadata, created_at)VALUES (line_id, p_preview_run_id, u.account_id, u.feature_key, u.usage_qty, unit_price, u.usage_qty * unit_price, OBJECT_CONSTRUCT(&#39;applied_rule&#39;, rule), CURRENT_TIMESTAMP());inserted := inserted + 1;  END FOR;  RETURN OBJECT_CONSTRUCT(&#39;preview_run_id&#39;, p_preview_run_id, &#39;inserted&#39;, inserted);END;$$;This stored-proc implements applying active rate rules to usage FOR billing preview per the rate-card/billing patterns.

AI_FEATURE_HUB.PROC_CREATE_RATE_RULE_SEED_DATA — Purpose: seed essential default rate rules AND templates IF missing (idempotent).

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_CREATE_RATE_RULE_SEED_DATA ()RETURNS VARIANTLANGUAGE SQLAS$$BEGIN  INSERT INTO AI_FEATURE_HUB.rate_rule_templates(template_id, org_id, name, template_definition, created_by, created_at)  SELECT &#39;template-default&#39;,&#39;_GLOBAL&#39;,&#39;default-rate-template&#39;, OBJECT_CONSTRUCT(&#39;default_unit_price&#39;,1.0,&#39;feature_keys&#39;,ARRAY_CONSTRUCT()), &#39;system&#39;, CURRENT_TIMESTAMP()  WHERE NOT EXISTS (SELECT 1 FROM AI_FEATURE_HUB.rate_rule_templates WHERE template_id = &#39;template-default&#39;);  INSERT INTO AI_FEATURE_HUB.rate_rules(rule_id, rule_definition, active, created_at)  SELECT &#39;rule-default&#39;, OBJECT_CONSTRUCT(&#39;rule_id&#39;,&#39;rule-default&#39;,&#39;default_unit_price&#39;,1.0,&#39;feature_keys&#39;,ARRAY_CONSTRUCT()), TRUE, CURRENT_TIMESTAMP()  WHERE NOT EXISTS (SELECT 1 FROM AI_FEATURE_HUB.rate_rules WHERE rule_id = &#39;rule-default&#39;);  RETURN OBJECT_CONSTRUCT(&#39;seeded&#39;, TRUE);END;$$;This idempotent seeding PROCEDURE follows the seed &amp; deployment ordering in the runbook.

AI_FEATURE_HUB.PROC_RUN_BILLING_SQL_ENHANCED — Purpose: SQL-only billing run (no external Python)that aggregates usage FOR a run window, computes line totals

USING RATE_RULES, AND inserts billing_runs + billing_line_items.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_RUN_BILLING_SQL_ENHANCED (p_run_id STRING, p_window_start TIMESTAMP_LTZ, p_window_end TIMESTAMP_LTZ, p_preview BOOLEAN DEFAULT TRUE)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE total_amount NUMBER := 0;BEGIN  CALL AI_FEATURE_HUB.PROC_CREATE_RATE_RULE_SEED_DATA();  INSERT INTO AI_FEATURE_HUB.billing_runs(run_id, run_ts, window_start, window_end, total_amount, status, created_at)  VALUES (p_run_id, CURRENT_TIMESTAMP(), p_window_start, p_window_end, 0, IFF(p_preview,&#39;PREVIEW&#39;,&#39;COMMITTED&#39;), CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.billing_line_items(line_id, run_id, account_id, product_code, qty, unit_price, line_total, metadata, created_at)  SELECT UUID_STRING(), u.account_id, u.account_id, u.feature_key, SUM(u.usage_qty) AS qty,COALESCE(r.rule_definition:default_unit_price::NUMBER, 0.0) AS unit_price,SUM(u.usage_qty) * COALESCE(r.rule_definition:default_unit_price::NUMBER, 0.0) AS line_total,OBJECT_CONSTRUCT(&#39;aggregated&#39;,TRUE),CURRENT_TIMESTAMP()


  FROM AI_FEATURE_HUB.tenant_feature_usage u  LEFT JOIN AI_FEATURE_HUB.rate_rules r    ON r.active = TRUE AND ARRAY_CONTAINS(r.rule_definition:feature_keys::ARRAY, u.feature_key)  WHERE u.event_ts &gt;= p_window_start AND u.event_ts &lt; p_window_end  GROUP BY u.account_id, u.feature_key, r.rule_definition:default_unit_price;  UPDATE AI_FEATURE_HUB.billing_runs SET total_amount = (SELECT SUM(line_total) FROM AI_FEATURE_HUB.billing_line_items WHERE run_id = p_run_id), updated_at = CURRENT_TIMESTAMP() WHERE run_id = p_run_id;  RETURN OBJECT_CONSTRUCT(&#39;run_id&#39;, p_run_id, &#39;status&#39;, IFF(p_preview,&#39;PREVIEW&#39;,&#39;COMMITTED&#39;));END;$$;This SQL-only billing run implements the preview/COMMIT flow without external imports
AS requested in some runbook variants.

AI_FEATURE_HUB.PROC_SCHEDULE_BILLING_TASK_IDEMPOTENT — Purpose: safely CREATE OR REPLACE a scheduled TASK that calls the SQL billing run;
RETURNS the task DDL executed.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_SCHEDULE_BILLING_TASK_IDEMPOTENT (p_task_name STRING, p_cron_expression STRING, p_warehouse STRING, p_run_window_minutes NUMBER)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE task_sql STRING;DECLARE run_id STRING := CONCAT(&#39;run-&#39;, TO_VARCHAR(CURRENT_TIMESTAMP()));BEGIN  task_sql := &#39;CREATE OR REPLACE TASK &#39; || IDENTIFIER(p_task_name) || &#39; WAREHOUSE=&#39;&#39;&#39; || p_warehouse || &#39;&#39;&#39; SCHEDULE = &#39;&#39;&#39; || p_cron_expression || &#39;&#39;&#39; AS CALL AI_FEATURE_HUB.PROC_RUN_BILLING_SQL_ENHANCED(&#39;&#39;&#39; || run_id || &#39;&#39;&#39;, DATEADD(minute, -&#39; || p_run_window_minutes || &#39;, CURRENT_TIMESTAMP()), CURRENT_TIMESTAMP(), TRUE);&#39;;  EXECUTE IMMEDIATE task_sql;  RETURN OBJECT_CONSTRUCT(&#39;task&#39;, p_task_name, &#39;task_sql&#39;, task_sql);END;$$;This follows the task-CREATE+resume idempotent pattern FOR scheduled billing shown in deployment examples.

AI_FEATURE_HUB.PROC_RECORD_TELEMETRY_EVENT — Purpose: INSERT a telemetry event FOR model calls, tasks, OR custom events AND maintain bounded history.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_RECORD_TELEMETRY_EVENT (p_event_id STRING, p_org_id STRING, p_event_type STRING, p_payload VARIANT)RETURNS STRINGLANGUAGE SQLAS$$BEGIN  INSERT INTO AI_FEATURE_HUB.model_telemetry(event_id, org_id, event_type, payload, created_at)  VALUES (p_event_id, p_org_id, p_event_type, p_payload, CURRENT_TIMESTAMP());  -- prune older telemetry to limit table growth (keep last 90 days)  DELETE FROM AI_FEATURE_HUB.model_telemetry WHERE created_at &lt; DATEADD(day, -90, CURRENT_TIMESTAMP());  RETURN p_event_id;END;$$;This telemetry ingestion pattern matches the telemetry/observability artifacts AND retention guidance.

AI_FEATURE_HUB.PROC_ROLLUP_TELEMETRY_DAILY_SUMMARY — Purpose: daily rollup of telemetry INTO telemetry_daily_summary table FOR SLOs.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_ROLLUP_TELEMETRY_DAILY_SUMMARY (p_summary_date DATE)RETURNS VARIANTLANGUAGE SQLAS$$BEGIN  INSERT INTO AI_FEATURE_HUB.telemetry_daily_summary(summary_date, org_id, model_calls, failed_calls, task_failures, created_at)  SELECT p_summary_date AS summary_date,org_id,COUNT_IF(event_type=&#39;MODEL_CALL&#39;) AS model_calls,COUNT_IF(event_type=&#39;MODEL_CALL&#39; AND payload:success::BOOLEAN = FALSE) AS failed_calls,(SELECT COUNT(*) FROM AI_FEATURE_HUB.task_runs tr WHERE DATE_TRUNC(&#39;day&#39;, tr.run_at) = p_summary_date AND tr.status = &#39;FAILED&#39;) AS task_failures,CURRENT_TIMESTAMP()


  FROM AI_FEATURE_HUB.model_telemetry  WHERE DATE_TRUNC(&#39;day&#39;, created_at) = p_summary_date  GROUP BY org_id;  RETURN OBJECT_CONSTRUCT(&#39;summary_date&#39;, p_summary_date);END;$$;This rollup mirrors the SLO/telemetry rollup components described in the ops artifacts.

AI_FEATURE_HUB.PROC_REGISTER_INDEX_SNAPSHOT_AND_ENQUEUE_BUILD — Purpose: register index snapshot manifest row AND enqueue a build job atomically (no external deletes).

