CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_REGISTER_INDEX_SNAPSHOT_AND_ENQUEUE_BUILD (p_snapshot_id STRING, p_s3_prefix STRING, p_org_id STRING, p_created_by STRING, p_meta VARIANT)RETURNS VARIANTLANGUAGE SQLAS$$BEGIN  INSERT INTO AI_FEATURE_HUB.index_snapshot_manifest(snapshot_id, s3_prefix, org_id, metadata, status, created_by, created_at)  VALUES (p_snapshot_id, p_s3_prefix, p_org_id, p_meta, &#39;REGISTERED&#39;, p_created_by, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.index_build_queue(queue_id, snapshot_id, status, enqueued_at)  VALUES (UUID_STRING(), p_snapshot_id, &#39;PENDING&#39;, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;snapshot_id&#39;, p_snapshot_id, &#39;enqueued&#39;, TRUE);END;$$;This follows the snapshot→S3→container pull pattern recommended FOR FAISS index management.

