CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_UPSERT_PIPELINE_CONFIG (p_pipeline_id STRING, p_org_id STRING, p_name STRING, p_config VARIANT, p_updated_by STRING)RETURNS VARIANTLANGUAGE SQLAS$$BEGIN  MERGE INTO AI_FEATURE_HUB.pipeline_configs tgt  USING (SELECT :p_pipeline_id AS pipeline_id) src ON tgt.pipeline_id = src.pipeline_id  WHEN MATCHED THEN UPDATE SET name = :p_name, config = :p_config, updated_by = :p_updated_by, updated_at = CURRENT_TIMESTAMP()  WHEN NOT MATCHED THEN INSERT (pipeline_id, org_id, name, config, created_by, created_at) VALUES (:p_pipeline_id, :p_org_id, :p_name, :p_config, :p_updated_by, CURRENT_TIMESTAMP());  INSERT INTO AI_FEATURE_HUB.pipeline_config_versions(version_id, pipeline_id, config_snapshot, created_by, created_at)  VALUES (UUID_STRING(), p_pipeline_id, p_config, p_updated_by, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;pipeline_id&#39;, p_pipeline_id);END;$$;This config/versioning approach follows the pipeline AND CI patterns in the ops documentation.

