CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_PRUNE_OLD_SEED_DATA (p_table_name STRING, p_older_than_days INT, p_requested_by STRING)RETURNS VARIANTLANGUAGE SQLAS$$DECLARE deleted_rows NUMBER := 0;BEGIN  EXECUTE IMMEDIATE &#39;DELETE FROM &#39; || :p_table_name || &#39; WHERE created_at &lt; DATEADD(day, -&#39; || p_older_than_days || &#39;, CURRENT_TIMESTAMP())&#39;;  SELECT ROW_COUNT() INTO :deleted_rows;  INSERT INTO AI_FEATURE_HUB.data_retention_audit(audit_id, table_name, deleted_rows, requested_by, created_at)  VALUES (UUID_STRING(), p_table_name, deleted_rows, p_requested_by, CURRENT_TIMESTAMP());  RETURN OBJECT_CONSTRUCT(&#39;table&#39;, p_table_name, &#39;deleted_rows&#39;, deleted_rows);END;$$;This retention/prune pattern follows the deployment AND retention notes FOR demo/seed data in the runbook.

