AI_FEATURE_HUB.PROC_VALIDATE_DEPLOYMENT_SMOKE_TEST — Purpose: run a small

SET of smoke queries to validate core objects AND

RETURN a JSON report.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PROC_VALIDATE_DEPLOYMENT_SMOKE_TEST ()RETURNS VARIANTLANGUAGE SQLAS$$DECLARE ok BOOLEAN := TRUE;DECLARE report VARIANT := OBJECT_CONSTRUCT();DECLARE cnt NUMBER;BEGIN  SELECT COUNT() INTO :cnt FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = &#39;AI_FEATURE_HUB&#39; AND TABLE_NAME IN (&#39;BILLING_RUNS&#39;,&#39;BILLING_LINE_ITEMS&#39;,&#39;RATE_RULES&#39;);  report := OBJECT_INSERT(report, &#39;core_tables_present&#39;, cnt);  IF cnt &lt; 3 THEN ok := FALSE; END IF;  SELECT COUNT() INTO :cnt FROM AI_FEATURE_HUB.billing_runs;  report := OBJECT_INSERT(report, &#39;billing_runs_count&#39;, cnt);  RETURN OBJECT_CONSTRUCT(&#39;ok&#39;, ok, &#39;report&#39;, report);END;$$;This smoke-test PROCEDURE implements the runbook verification checks recommended after deployment.

