AI_FEATURE_HUB.GET_OPEN_FOLLOWUP_TASKS_BY_INSTANCE

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.GET_OPEN_FOLLOWUP_TASKS_BY_INSTANCE (instance_ref STRING, feature_key STRING, org_id STRING)RETURNS VARIANT

LANGUAGE SQL

AS
$$
SELECT ARRAY_AGG(OBJECT_CONSTRUCT_KEEP_NULL(
  &#39;task_id&#39;, task_id,
  &#39;incident_id&#39;, incident_id,
  &#39;assigned_to&#39;, assigned_to,
  &#39;due_at&#39;, due_at,
  &#39;status&#39;, status,
  &#39;task_details&#39;, task_details,
  &#39;created_at&#39;, created_at,
  &#39;updated_at&#39;, updated_at
)) AS open_tasks
FROM AI_FEATURE_HUB.incident_followup_tasks
WHERE instance_ref = :instance_ref
  AND feature_key = :feature_key
  AND org_id = :org_id
  AND status != &#39;CLOSED&#39;;
$$;

AI_FEATURE_HUB.ASSIGN_FOLLOWUP_BATCH

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.ASSIGN_FOLLOWUP_BATCH (assignment_batch_id STRING, org_id STRING, task_ids ARRAY, assignee STRING, assigned_by STRING)RETURNS STRING

LANGUAGE SQL

AS
$$
-- idempotent batch assign: record assignment rows and update tasks
FOR t IN (SELECT VALUE AS task_id FROM TABLE(FLATTEN(INPUT =&gt; :task_ids)))
  DO
    MERGE INTO AI_FEATURE_HUB.incident_followup_assignments tgt
    USING (SELECT t.task_id AS task_id) src
    ON tgt.task_id = src.task_id AND tgt.org_id = :org_id
    WHEN MATCHED THEN UPDATE SET assignee = :assignee, assigned_by = :assigned_by, assigned_at = CURRENT_TIMESTAMP()
    WHEN NOT MATCHED THEN INSERT (assignment_id, task_id, org_id, assignee, assigned_by, assigned_at)
      VALUES (CONCAT(&#39;fa_&#39;, UUID_STRING()), src.task_id, :org_id, :assignee, :assigned_by, CURRENT_TIMESTAMP());
    UPDATE AI_FEATURE_HUB.incident_followup_tasks SET assigned_to = :assignee, updated_at = CURRENT_TIMESTAMP() WHERE task_id = t.task_id AND org_id = :org_id;
  END FOR;
RETURN :assignment_batch_id;
$$;

AI_FEATURE_HUB.BULK_UPDATE_FOLLOWUP_STATUS

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.BULK_UPDATE_FOLLOWUP_STATUS (update_batch_id STRING, org_id STRING, task_ids ARRAY, new_status STRING, updated_by STRING)RETURNS STRING

LANGUAGE SQL

AS
$$
FOR t IN (SELECT VALUE AS task_id FROM TABLE(FLATTEN(INPUT =&gt; :task_ids)))
  DO
    UPDATE AI_FEATURE_HUB.incident_followup_tasks
    SET status = :new_status, updated_at = CURRENT_TIMESTAMP()
    WHERE task_id = t.task_id AND org_id = :org_id;
    INSERT INTO AI_FEATURE_HUB.incident_followup_task_audit(audit_id, task_id, org_id, action, actor, details, acted_at)
    VALUES (CONCAT(&#39;fta_&#39;, UUID_STRING()), t.task_id, :org_id, &#39;STATUS_UPDATE&#39;, :updated_by, OBJECT_CONSTRUCT(&#39;new_status&#39;, :new_status), CURRENT_TIMESTAMP());
  END FOR;
RETURN :update_batch_id;
$$;

