AI_FEATURE_HUB.ARCHIVE_FOLLOWUP_TASKS

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.ARCHIVE_FOLLOWUP_TASKS (archive_job_id STRING, org_id STRING, criteria VARIANT, archived_by STRING)RETURNS STRING

LANGUAGE SQL

AS
$$
-- Move matching tasks to archive table and mark original rows
INSERT INTO AI_FEATURE_HUB.incident_followup_tasks_archive
SELECT *, CURRENT_TIMESTAMP() AS archived_at FROM AI_FEATURE_HUB.incident_followup_tasks
WHERE org_id = :org_id AND ( :criteria IS NULL OR OBJECT_CONTAINS(OBJECT_CONSTRUCT_KEEP_NULL(&#39;criteria&#39;, :criteria), &#39;criteria&#39;) = TRUE ); -- caller should pass explicit WHERE-compatible criteria representation
DELETE FROM AI_FEATURE_HUB.incident_followup_tasks WHERE org_id = :org_id AND status = &#39;CLOSED&#39; AND DATE_DIFF(&#39;day&#39;, updated_at, CURRENT_TIMESTAMP()) &gt; COALESCE(:criteria:older_than_days, 90);
INSERT INTO AI_FEATURE_HUB.incident_followup_task_audit(audit_id, task_id, org_id, action, actor, details, acted_at)
VALUES (CONCAT(&#39;fta_&#39;, UUID_STRING()), NULL, :org_id, &#39;ARCHIVE_BATCH&#39;, :archived_by, :criteria, CURRENT_TIMESTAMP());
RETURN :archive_job_id;
$$;

AI_FEATURE_HUB.RESTORE_FOLLOWUP_TASK

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.RESTORE_FOLLOWUP_TASK (task_id STRING, org_id STRING, restored_by STRING)RETURNS STRING

LANGUAGE SQL

AS
$$
INSERT INTO AI_FEATURE_HUB.incident_followup_tasks
SELECT * EXCLUDE(archived_at) FROM AI_FEATURE_HUB.incident_followup_tasks_archive
WHERE task_id = :task_id AND org_id = :org_id;
DELETE FROM AI_FEATURE_HUB.incident_followup_tasks_archive WHERE task_id = :task_id AND org_id = :org_id;
INSERT INTO AI_FEATURE_HUB.incident_followup_task_audit(audit_id, task_id, org_id, action, actor, details, acted_at)
VALUES (CONCAT(&#39;fta_&#39;, UUID_STRING()), :task_id, :org_id, &#39;RESTORE&#39;, :restored_by, NULL, CURRENT_TIMESTAMP());
RETURN :task_id;
$$;

AI_FEATURE_HUB.VALIDATE_FOLLOWUP_REFERENCES

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.VALIDATE_FOLLOWUP_REFERENCES (validation_id STRING, org_id STRING, sample_limit INT DEFAULT 100)RETURNS VARIANT

LANGUAGE SQL

AS
$$
-- Check referential integrity between followup tasks and incidents/tasks table
WITH sample AS (
  SELECT task_id, incident_id FROM AI_FEATURE_HUB.incident_followup_tasks WHERE org_id = :org_id LIMIT :sample_limit
),
missing_incidents AS (
  SELECT s.task_id, s.incident_id FROM sample s
  LEFT JOIN AI_FEATURE_HUB.incidents i ON i.incident_id = s.incident_id AND i.org_id = :org_id
  WHERE i.incident_id IS NULL
)
SELECT OBJECT_CONSTRUCT(&#39;validation_id&#39;, :validation_id, &#39;org_id&#39;, :org_id, &#39;missing_count&#39;, (SELECT COUNT(*) FROM missing_incidents), &#39;sample_limit&#39;, :sample_limit) AS result;
$$;

