;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.REMOVE_FOLLOWUP_ATTACHMENT (attachment_id STRING, task_id STRING, org_id STRING, removed_by STRING)RETURNS STRING

LANGUAGE SQL

AS
$$
DELETE FROM AI_FEATURE_HUB.incident_followup_attachments WHERE attachment_id = :attachment_id AND task_id = :task_id AND org_id = :org_id;
INSERT INTO AI_FEATURE_HUB.incident_followup_task_audit(audit_id, task_id, org_id, action, actor, details, acted_at)
VALUES (CONCAT(&#39;fta_&#39;, UUID_STRING()), :task_id, :org_id, &#39;REMOVE_ATTACHMENT&#39;, :removed_by, :attachment_id, CURRENT_TIMESTAMP());
RETURN :attachment_id;
$$;

