AI_FEATURE_HUB.GENERATE_FOLLOWUP_METRICS

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.GENERATE_FOLLOWUP_METRICS (metrics_id STRING, org_id STRING, window_start TIMESTAMP_LTZ, window_end TIMESTAMP_LTZ)RETURNS VARIANT

LANGUAGE SQL

AS
$$
-- compute simple metrics: open count, avg time to close, overdue count
WITH window_tasks AS (
  SELECT * FROM AI_FEATURE_HUB.incident_followup_tasks
  WHERE org_id = :org_id AND created_at BETWEEN :window_start AND :window_end
)
SELECT OBJECT_CONSTRUCT_KEEP_NULL(
  &#39;metrics_id&#39;, :metrics_id,
  &#39;org_id&#39;, :org_id,
  &#39;window_start&#39;, :window_start,
  &#39;window_end&#39;, :window_end,
  &#39;open_count&#39;, (SELECT COUNT(*) FROM window_tasks WHERE status != &#39;CLOSED&#39;),
  &#39;closed_count&#39;, (SELECT COUNT(*) FROM window_tasks WHERE status = &#39;CLOSED&#39;),
  &#39;avg_time_to_close_seconds&#39;, (SELECT AVG(DATEDIFF(&#39;second&#39;, created_at, closed_at)) FROM window_tasks WHERE status = &#39;CLOSED&#39;),
  &#39;overdue_count&#39;, (SELECT COUNT(*) FROM window_tasks WHERE due_at IS NOT NULL AND due_at &lt; CURRENT_TIMESTAMP() AND status != &#39;CLOSED&#39;)
) AS metrics;
$$;

AI_FEATURE_HUB.RECONCILE_FOLLOWUP_WITH_INCIDENTS

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.RECONCILE_FOLLOWUP_WITH_INCIDENTS (reconcile_id STRING, org_id STRING, sample_limit INT DEFAULT 1000)RETURNS VARIANT

LANGUAGE SQL

AS
$$
-- find followups that reference non-existent incidents or mismatched org
WITH candidates AS (
  SELECT task_id, incident_id, org_id AS followup_org
  FROM AI_FEATURE_HUB.incident_followup_tasks
  WHERE org_id = :org_id
  LIMIT :sample_limit
),
missing AS (
  SELECT c.task_id, c.incident_id FROM candidates c
  LEFT JOIN AI_FEATURE_HUB.incidents i ON i.incident_id = c.incident_id
  WHERE i.incident_id IS NULL
)
SELECT OBJECT_CONSTRUCT(&#39;reconcile_id&#39;, :reconcile_id, &#39;org_id&#39;, :org_id, &#39;sample_limit&#39;, :sample_limit, &#39;missing_count&#39;, (SELECT COUNT(*) FROM missing)) AS result;
$$;

AI_FEATURE_HUB.PURGE_STALE_FOLLOWUPS

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.PURGE_STALE_FOLLOWUPS (purge_job_id STRING, org_id STRING, older_than_days INT, dry_run BOOLEAN DEFAULT TRUE, executed_by STRING)RETURNS VARIANT

LANGUAGE SQL

AS
$$
-- Return list of candidate task_ids; delete only when dry_run = FALSE
WITH candidates AS (
  SELECT task_id FROM AI_FEATURE_HUB.incident_followup_tasks
  WHERE org_id = :org_id AND status = &#39;CLOSED&#39; AND DATE_DIFF(&#39;day&#39;, updated_at, CURRENT_TIMESTAMP()) &gt; :older_than_days
)
SELECT
  OBJECT_CONSTRUCT(
    &#39;purge_job_id&#39;, :purge_job_id,
    &#39;org_id&#39;, :org_id,
    &#39;older_than_days&#39;, :older_than_days,
    &#39;dry_run&#39;, :dry_run,
    &#39;candidate_count&#39;, (SELECT COUNT(*) FROM candidates)
  ) AS summary
;
-- perform deletion if allowed
IF :dry_run = FALSE THEN
  DELETE FROM AI_FEATURE_HUB.incident_followup_tasks WHERE task_id IN (SELECT task_id FROM candidates);
  INSERT INTO AI_FEATURE_HUB.incident_followup_task_audit(audit_id, task_id, org_id, action, actor, details, acted_at)
  SELECT CONCAT(&#39;fta_&#39;, UUID_STRING()), task_id, :org_id, &#39;PURGE&#39;, :executed_by, OBJECT_CONSTRUCT(&#39;older_than_days&#39;, :older_than_days), CURRENT_TIMESTAMP()
  FROM candidates;
END IF;
$$;

