CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.APPLY_PII_MASKING_TO_SCHEMA (target_schema STRING)RETURNS STRINGLANGUAGE JAVASCRIPTAS$$var schema = INPUT_SCHEMA;var sql =   SELECT table_name, column_name   FROM information_schema.columns   WHERE table_schema = :1 AND tag_value = &#39;PII&#39;;;var stmt = snowflake.createStatement({sqlText: sql, binds: [TARGET_SCHEMA]});var rs = stmt.execute();while (rs.next()) {  var tbl = rs.getColumnValue(1);  var col = rs.getColumnValue(2);  var alter = ALTER TABLE  + TARGET_SCHEMA + . + tbl + MODIFY COLUMN + col +  SET MASKING POLICY tag_based_mask_pii;;  snowflake.createStatement({sqlText: alter}).execute();}return &#39;OK&#39;;$$;

