CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0544_approve_rate_rule (staging_id STRING, approver STRING, approval_note STRING)RETURNS STRINGLANGUAGE SQLAS$$-- mark staging approved, merge to RATE_RULES, write auditUPDATE AI_FEATURE_HUB.rate_rules_stagingSET status = &#39;APPROVED&#39;, approved_by = :approver, approved_at = CURRENT_TIMESTAMP(), approval_note = :approval_noteWHERE staging_id = :staging_id;


MERGE INTO AI_FEATURE_HUB.rate_rules tgtUSING (  SELECT staging_id, org_id, rate_rule  FROM AI_FEATURE_HUB.rate_rules_staging  WHERE staging_id = :staging_id AND status = &#39;APPROVED&#39;) srcON tgt.org_id = src.org_id AND tgt.rate_rule-&gt;&gt;&#39;rule_id&#39; = src.rate_rule-&gt;&gt;&#39;rule_id&#39;WHEN MATCHED THEN  UPDATE SET rate_rule = src.rate_rule, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN  INSERT (org_id, rate_rule, created_at, updated_at)  VALUES (src.org_id, src.rate_rule, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP());
INSERT INTO AI_FEATURE_HUB.rate_rules_audit(audit_id, staging_id, action, acted_by, acted_at, details)VALUES (UUID_STRING(), :staging_id, &#39;APPROVE&#39;, :approver, CURRENT_TIMESTAMP(), OBJECT_CONSTRUCT(&#39;note&#39;, :approval_note));
RETURN :staging_id;$$;This implements a pure-SQL approve/MERGE/audit flow FOR rate rules consistent with the submit/approve staging pattern in your designs.

