;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0545_reject_rate_rule (staging_id STRING, approver STRING, rejection_reason STRING)RETURNS STRINGLANGUAGE SQLAS$$UPDATE AI_FEATURE_HUB.rate_rules_stagingSET status = &#39;REJECTED&#39;, approved_by = :approver, approved_at = CURRENT_TIMESTAMP(), approval_note = :rejection_reasonWHERE staging_id = :staging_id;

INSERT INTO AI_FEATURE_HUB.rate_rules_audit(audit_id, staging_id, action, acted_by, acted_at, details)VALUES (UUID_STRING(), :staging_id, &#39;REJECT&#39;, :approver, CURRENT_TIMESTAMP(), OBJECT_CONSTRUCT(&#39;reason&#39;, :rejection_reason));
RETURN :staging_id;$$;This SQL-only reject flow records staging state AND writes audit rows per the approval-staging designs.

