CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0546_persist_billing_runs (run_cutoff_minutes NUMBER DEFAULT 60, preview_only BOOLEAN DEFAULT TRUE)RETURNS VARIANTLANGUAGE SQLAS$$-- Persist billing preview rows older than run_cutoff_minutes into persistent billing tablesINSERT INTO AI_FEATURE_HUB.subscription_invoices (invoice_id, account_id, run_id, invoice_payload, created_at)SELECT bp.invoice_id, bp.account_id, bp.run_id, bp.invoice_payload, CURRENT_TIMESTAMP()FROM AI_FEATURE_HUB.billing_preview bpWHERE bp.created_at &lt; DATEADD(minute, -:run_cutoff_minutes, CURRENT_TIMESTAMP())  AND (:preview_only = FALSE OR bp.is_finalized = TRUE);

-- Optionally remove persisted preview rows only when preview_only = FALSEIF (:preview_only = FALSE) THEN  DELETE FROM AI_FEATURE_HUB.billing_preview  WHERE created_at &lt; DATEADD(minute, -:run_cutoff_minutes, CURRENT_TIMESTAMP());END IF;
RETURN OBJECT_CONSTRUCT(&#39;persisted_before_minutes&#39;, :run_cutoff_minutes, &#39;preview_only&#39;, :preview_only);$$;This implements the persist-

FROM-preview pattern FOR billing runs AND follows the preview/persist guidance in your billing artifacts.

