;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0547_reconcile_billing_vs_usage (account_id STRING DEFAULT NULL, window_start TIMESTAMP_LTZ DEFAULT NULL, window_end TIMESTAMP_LTZ DEFAULT NULL)RETURNS VARIANTLANGUAGE SQLAS$$-- Identify mismatches between billing line items and aggregated usageINSERT INTO AI_FEATURE_HUB.reconciliation_audit(audit_id, account_id, run_at, mismatch_details)SELECT UUID_STRING(), COALESCE(:account_id, u.account_id), CURRENT_TIMESTAMP(),  OBJECT_CONSTRUCT(&#39;billed&#39;, COALESCE(b.total_billed,0), &#39;usage&#39;, COALESCE(u.total_usage,0))FROM (  SELECT account_id, SUM(quantity) AS total_usage  FROM AI_FEATURE_HUB.tenant_feature_usage  WHERE (:window_start IS NULL OR usage_ts &gt;= :window_start) AND (:window_end IS NULL OR usage_ts &lt;= :window_end)  GROUP BY account_id) uLEFT JOIN (  SELECT account_id, SUM(amount) AS total_billed  FROM AI_FEATURE_HUB.billing_line_items  WHERE (:window_start IS NULL OR billed_at &gt;= :window_start) AND (:window_end IS NULL OR billed_at &lt;= :window_end)  GROUP BY account_id) bON u.account_id = b.account_idWHERE COALESCE(b.total_billed,0) != COALESCE(u.total_usage,0)  AND (:account_id IS NULL OR u.account_id = :account_id);

RETURN OBJECT_CONSTRUCT(&#39;account_provided&#39;, :account_id, &#39;window_start&#39;, :window_start, &#39;window_end&#39;, :window_end);$$;This reconciliation PROCEDURE writes mismatch records per the reconcile patterns in your billing/recon docs.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0548_run_billing_enhanced (run_id STRING, run_start TIMESTAMP_LTZ, run_end TIMESTAMP_LTZ, account_id STRING DEFAULT NULL, dry_run BOOLEAN DEFAULT TRUE)RETURNS VARIANTLANGUAGE SQLAS$$-- Create billing run metadataINSERT INTO AI_FEATURE_HUB.billing_run (run_id, run_start, run_end, account_id, dry_run, created_at)VALUES (:run_id, :run_start, :run_end, :account_id, :dry_run, CURRENT_TIMESTAMP());

-- Generate line items using rate rules and usageINSERT INTO AI_FEATURE_HUB.billing_line_items(line_item_id, run_id, account_id, feature_key, quantity, unit_price, amount, billed_at)SELECT  UUID_STRING(),  :run_id,  u.account_id,  u.feature_key,  u.total_qty,  COALESCE(rr.rate::NUMBER, 0),  COALESCE(u.total_qty,0) * COALESCE(rr.rate::NUMBER,0),  CURRENT_TIMESTAMP()FROM (  SELECT account_id, feature_key, SUM(quantity) AS total_qty  FROM AI_FEATURE_HUB.tenant_feature_usage  WHERE usage_ts &gt;= :run_start AND usage_ts &lt; :run_end    AND (:account_id IS NULL OR account_id = :account_id)  GROUP BY account_id, feature_key) uLEFT JOIN AI_FEATURE_HUB.rate_rules rr  ON rr.org_id = (SELECT org_id FROM AI_FEATURE_HUB.accounts WHERE account_id = u.account_id LIMIT 1)  AND rr.rate_rule-&gt;&gt;&#39;feature_key&#39; = u.feature_key;
-- If not dry_run, mark run finalizedIF (:dry_run = FALSE) THEN  UPDATE AI_FEATURE_HUB.billing_run SET finalized = TRUE, finalized_at = CURRENT_TIMESTAMP() WHERE run_id = :run_id;END IF;
RETURN OBJECT_CONSTRUCT(&#39;run_id&#39;, :run_id, &#39;dry_run&#39;, :dry_run);$$;This enhanced billing run follows the rate application AND preview/persist patterns described in your billing designs.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0549_get_feature_usage_summary (feature_key STRING, window_start TIMESTAMP_LTZ DEFAULT DATEADD (month, -1, CURRENT_TIMESTAMP ()), window_end TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP ())RETURNS VARIANTLANGUAGE SQLAS$$RETURN (  SELECT ARRAY_AGG(OBJECT_CONSTRUCT(&#39;org_id&#39;, org_id, &#39;account_id&#39;, account_id, &#39;feature_key&#39;, feature_key, &#39;total_usage&#39;, total_usage))  FROM (SELECT org_id, account_id, feature_key, SUM(quantity) AS total_usageFROM AI_FEATURE_HUB.tenant_feature_usageWHERE feature_key = :feature_key AND usage_ts &gt;= :window_start AND usage_ts &lt;= :window_endGROUP BY org_id, account_id, feature_key  ));$$;This PROCEDURE
