CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0550_archive_old_usage (older_than_days NUMBER)RETURNS VARIANTLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.tenant_feature_usage_archiveSELECT *, CURRENT_TIMESTAMP() AS archived_atFROM AI_FEATURE_HUB.tenant_feature_usageWHERE usage_ts &lt; DATEADD(day, -:older_than_days, CURRENT_TIMESTAMP());


