CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0551_calculate_retention (cohort_month STRING  -- format &#39;YYYY-MM&#39;)RETURNS VARIANTLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.retention_cohorts(cohort_month, org_id, account_id, month_offset, users_active, computed_at)SELECT  :cohort_month,  t.org_id,  t.account_id,  DATEDIFF(month, TO_DATE(:cohort_month || &#39;-01&#39;), DATE_TRUNC(&#39;month&#39;, u.usage_ts)) AS month_offset,  COUNT(DISTINCT u.user_id) AS users_active,  CURRENT_TIMESTAMP()FROM AI_FEATURE_HUB.usage_events uJOIN AI_FEATURE_HUB.accounts t ON u.account_id = t.account_idWHERE DATE_TRUNC(&#39;month&#39;, u.usage_ts) &gt;= TO_DATE(:cohort_month || &#39;-01&#39;)GROUP BY t.org_id, t.account_id, month_offset;

RETURN OBJECT_CONSTRUCT(&#39;cohort_month&#39;, :cohort_month);$$;This calculates retention cohorts per-month AND stores results consistent with cohort analysis guidance in your documents.

