CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0552_entitlement_check (account_id STRING, feature_key STRING)RETURNS VARIANTLANGUAGE SQLAS$$RETURN (  SELECT OBJECT_CONSTRUCT(&#39;account_id&#39;, a.account_id,&#39;feature_key&#39;, :feature_key,&#39;entitled&#39;, CASE WHEN afp.account_id IS NOT NULL THEN TRUE ELSE FALSE END,&#39;details&#39;, OBJECT_CONSTRUCT(&#39;pricing&#39;, afp)  )  FROM AI_FEATURE_HUB.accounts a  LEFT JOIN AI_FEATURE_HUB.account_feature_pricing afpON afp.account_id = a.account_id AND afp.feature_key = :feature_key  WHERE a.account_id = :account_id  LIMIT 1);$$;This
