CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0602_create_document_instance (document_id STRING, template_version_id STRING, requester STRING, input_context VARIANT, status STRING DEFAULT &#39;PENDING&#39;)RETURNS STRINGLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.document_instances(document_id, template_version_id, requester, input_context, status, created_at)VALUES (:document_id, :template_version_id, :requester, :input_context, :status, CURRENT_TIMESTAMP());RETURN :document_id;$$Creates a document instance row (request + context)to drive assembly AND provenance capture
AS required by the DocGen runtime.

