CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0603_merge_document_with_clauses (document_id STRING, resolved_clauses VARIANT, assembly_log VARIANT)RETURNS STRINGLANGUAGE SQLAS$$UPDATE AI_FEATURE_HUB.document_instancesSET resolved_clauses = :resolved_clauses, assembly_log = :assembly_log, status = &#39;ASSEMBLED&#39;, assembled_at = CURRENT_TIMESTAMP()WHERE document_id = :document_id;RETURN :document_id;$$Performs the in-DB MERGE of template + selected clauses AND records assembly provenance FOR explainability/audit.

AI_FEATURE_HUB.proc_docgen_0604_mark_document_rendered

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0604_mark_document_rendered (document_id STRING, renderer STRING, render_format STRING, rendered_uri STRING, render_metadata VARIANT)RETURNS STRINGLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.rendered_documents(render_id, document_id, renderer, render_format, rendered_uri, render_metadata, rendered_at)VALUES (UUID_STRING(), :document_id, :renderer, :render_format, :rendered_uri, :render_metadata, CURRENT_TIMESTAMP());UPDATE AI_FEATURE_HUB.document_instances SET status = &#39;RENDERED&#39;, last_render_id = (SELECT render_id FROM AI_FEATURE_HUB.rendered_documents WHERE document_id = :document_id ORDER BY rendered_at DESC LIMIT 1) WHERE document_id = :document_id;RETURN (SELECT render_id FROM AI_FEATURE_HUB.rendered_documents WHERE document_id = :document_id ORDER BY rendered_at DESC LIMIT 1);$$Records renderer output AND marks document instance
AS rendered; this preserves rendered artifacts AND links to provenance.

AI_FEATURE_HUB.proc_docgen_0605_seal_document_and_store_evidence

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0605_seal_document_and_store_evidence (document_id STRING, seal_id STRING, evidence_blob VARIANT, sealed_by STRING)RETURNS STRINGLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.evidence_bundles(evidence_id, document_id, seal_id, evidence_blob, sealed_by, sealed_at)VALUES (:seal_id, :document_id, :seal_id, :evidence_blob, :sealed_by, CURRENT_TIMESTAMP());UPDATE AI_FEATURE_HUB.document_instances SET status = &#39;SEALED&#39;, sealed_evidence_id = :seal_id WHERE document_id = :document_id;RETURN :seal_id;$$Packages AND persists the CompliancePacket / evidence bundle AND marks the document sealed FOR compliance/audit trails.

AI_FEATURE_HUB.proc_docgen_0606_ingest_embeddings_batch

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0606_ingest_embeddings_batch (batch_id STRING, embedding_rows VARIANT)RETURNS STRINGLANGUAGE SQLAS$$-- embedding_rows expected as an ARRAY of OBJECTS with keys: document_id, section_id, vector, metadataINSERT INTO AI_FEATURE_HUB.document_embeddings(document_id, section_id, vector, metadata, ingested_at)SELECT value:document_id::STRING, value:section_id::STRING, value:vector, value:metadata, CURRENT_TIMESTAMP()FROM TABLE(FLATTEN(input =&gt; PARSE_JSON(:embedding_rows)));RETURN :batch_id;$$Idempotent batch ingest FOR document embeddings INTO the canonical embedding store used FOR retrieval AND index export.

AI_FEATURE_HUB.proc_docgen_0607_merge_embeddings_into_vectorstore

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0607_merge_embeddings_into_vectorstore (source_batch_id STRING, upsert_key STRING)RETURNS STRINGLANGUAGE SQLAS$$MERGE INTO AI_FEATURE_HUB.document_embeddings_vectorstore tgtUSING (SELECT * FROM AI_FEATURE_HUB.document_embeddings WHERE batch_id = :source_batch_id) srcON tgt.document_id = src.document_id AND tgt.section_id = src.section_idWHEN MATCHED THEN UPDATE SET vector = src.vector, metadata = src.metadata, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT (document_id, section_id, vector, metadata, created_at) VALUES (src.document_id, src.section_id, src.vector, src.metadata, CURRENT_TIMESTAMP());RETURN :source_batch_id;$$Consolidates ingested embedding batches INTO the main vectorstore table with upsert semantics FOR uniqueness.

AI_FEATURE_HUB.proc_docgen_0608_export_embeddings_to_s3_snapshot

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0608_export_embeddings_to_s3_snapshot (snapshot_id STRING, s3_prefix STRING, min_modified_after TIMESTAMP_LTZ DEFAULT NULL)RETURNS STRINGLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.embedding_snapshot_manifest(snapshot_id, s3_prefix, exported_at)SELECT :snapshot_id, :s3_prefix, CURRENT_TIMESTAMP();-- Export query (user must configure stage/external location) writes vectors/ids to staged files per manifest patternCOPY INTO &#39;@MY_S3_STAGE/&#39; || :s3_prefix || &#39;/&#39; || :snapshot_id || &#39;.ndjson&#39;FROM (SELECT OBJECT_CONSTRUCT(&#39;document_id&#39;, document_id, &#39;section_id&#39;, section_id, &#39;vector&#39;, vector, &#39;metadata&#39;, metadata) FROM AI_FEATURE_HUB.document_embeddings WHERE (:min_modified_after IS NULL OR modified_at &gt; :min_modified_after))FILE_FORMAT = (TYPE = &#39;NDJSON&#39;) OVERWRITE = TRUE;RETURN :snapshot_id;$$Exports embeddings to an S3 snapshot manifest to support FAISS/ANN snapshot loader workflows described in the design.

AI_FEATURE_HUB.proc_docgen_0609_register_faiss_snapshot

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0609_register_faiss_snapshot (snapshot_id STRING, s3_prefix STRING, shard_count INT, created_by STRING)RETURNS STRINGLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.faiss_snapshots(snapshot_id, s3_prefix, shard_count, status, created_by, created_at)VALUES (:snapshot_id, :s3_prefix, :shard_count, &#39;REGISTERED&#39;, :created_by, CURRENT_TIMESTAMP());RETURN :snapshot_id;$$Registers a FAISS snapshot manifest (S3 prefix + shard info)so index-build containers can pick up AND CREATE ANN shards.

AI_FEATURE_HUB.proc_docgen_0610_request_faiss_index_refresh

