CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0613_apply_ratecard_to_usage (usage_id STRING, account_id STRING, feature_key STRING, units NUMBER)RETURNS VARIANTLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.billing_line_items(line_item_id, usage_id, account_id, feature_key, units, unit_price, total_price, created_at)SELECT UUID_STRING(), :usage_id, :account_id, :feature_key, :units, COALESCE(r.price_per_unit,0), COALESCE(r.price_per_unit,0)*:units, CURRENT_TIMESTAMP()FROM AI_FEATURE_HUB.rate_cards rWHERE r.feature_key = :feature_keyAND r.effective_from &lt;= CURRENT_TIMESTAMP()AND r.effective_to &gt;= CURRENT_TIMESTAMP();RETURN OBJECT_CONSTRUCT(&#39;usage_id&#39;, :usage_id, &#39;status&#39;, &#39;BILLED&#39;);$$Applies effective ratecard pricing to a usage event AND inserts a billing line item FOR the billing preview/run flows.

