CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_0614_reconcile_billing_adjustments (reconcile_id STRING, billing_run_id STRING)RETURNS STRINGLANGUAGE SQLAS$$INSERT INTO AI_FEATURE_HUB.billing_reconciliation(reconcile_id, billing_run_id, created_at)VALUES (:reconcile_id, :billing_run_id, CURRENT_TIMESTAMP());-- Example reconciliation step: flag discrepancies in BILLING_LINE_ITEM vs USAGE_EVENTSINSERT INTO AI_FEATURE_HUB.billing_reconciliation_details(detail_id, reconcile_id, usage_id, billed_amount, usage_amount, discrepancy, detected_at)SELECT UUID_STRING(), :reconcile_id, u.usage_id, COALESCE(b.total_price,0), COALESCE(u.estimated_cost,0), COALESCE(b.total_price,0)-COALESCE(u.estimated_cost,0), CURRENT_TIMESTAMP()FROM AI_FEATURE_HUB.usage_events uLEFT JOIN AI_FEATURE_HUB.billing_line_items b ON b.usage_id = u.usage_idWHERE b.billing_run_id = :billing_run_id;RETURN :reconcile_id;$$Performs reconciliation between usage events AND billing line items AND records detected discrepancies FOR audit.

