AS $$RETURN (SELECT OBJECT_CONSTRUCT_KEEP_NULL(  &#39;incident_id&#39;, incident_id,  &#39;total_followups&#39;, (SELECT COUNT() FROM AI_FEATURE_HUB.docgen_feature_instance_incident_followups WHERE incident_id = :incident_id),  &#39;open_followups&#39;, (SELECT COUNT() FROM AI_FEATURE_HUB.docgen_feature_instance_incident_followups WHERE incident_id = :incident_id AND followup_status NOT IN (&#39;RESOLVED&#39;,&#39;CLOSED&#39;)),  &#39;last_followup_at&#39;, (SELECT MAX(updated_at) FROM AI_FEATURE_HUB.docgen_feature_instance_incident_followups WHERE incident_id = :incident_id)));$$;Consolidated

FROM reporting/summary view patterns AND OBJECT_CONSTRUCT usage seen in the delivered materials

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_96_mark_followup_as_blocked (followup_id STRING, blocked_by STRING, block_reason VARIANT)RETURNS STRING
LANGUAGE SQL
AS $$UPDATE AI_FEATURE_HUB.docgen_feature_instance_incident_followupsSET followup_status = &#39;BLOCKED&#39;, blocked_by = :blocked_by, block_reason = :block_reason, blocked_at = CURRENT_TIMESTAMP()WHERE followup_id = :followup_id;INSERT INTO AI_FEATURE_HUB.docgen_followup_history(history_id, followup_id, event_type, event_payload, created_at) VALUES (SYSTEM$UUID(), :followup_id, &#39;BLOCKED&#39;, :block_reason, CURRENT_TIMESTAMP());RETURN :followup_id;$$;Consolidated

FROM status-change AND history/audit prototypes in the repository artifacts

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_97_unblock_followup_and_resume (followup_id STRING, resumed_by STRING, resume_notes VARIANT)RETURNS STRING
LANGUAGE SQL
AS $$UPDATE AI_FEATURE_HUB.docgen_feature_instance_incident_followupsSET followup_status = &#39;OPEN&#39;, resumed_by = :resumed_by, resumed_at = CURRENT_TIMESTAMP(), resume_notes = :resume_notesWHERE followup_id = :followup_id;INSERT INTO AI_FEATURE_HUB.docgen_followup_history(history_id, followup_id, event_type, event_payload, created_at) VALUES (SYSTEM$UUID(), :followup_id, &#39;RESUMED&#39;, :resume_notes, CURRENT_TIMESTAMP());RETURN :followup_id;$$;Consolidated

FROM resume/unblock patterns AND history logging examples in the provided documents

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_98_bulk_import_followups_from_stage (staged_file_path STRING, org_id STRING)RETURNS NUMBER
LANGUAGE SQL
AS $$-- expects JSONL file staged into user stage; file contains array of objects with followup_id, incident_id, instance_ref, feature_key, created_by, followup_payloadCOPY INTO AI_FEATURE_HUB.docgen_feature_instance_incident_followups (followup_id, incident_id, instance_ref, feature_key, org_id, followup_payload, created_by, created_at)FROM ( SELECT t.$1:followup_id::STRING, t.$1:incident_id::STRING, t.$1:instance_ref::STRING, t.$1:feature_key::STRING, :org_id, t.$1:followup_payload::VARIANT, t.$1:created_by::STRING, CURRENT_TIMESTAMP()       FROM @%AI_FEATURE_HUB.docgen_feature_instance_incident_followups (FILE =&gt; :staged_file_path) t )ON_ERROR = &#39;CONTINUE&#39;;RETURN (SELECT COUNT(*) FROM AI_FEATURE_HUB.docgen_feature_instance_incident_followups WHERE org_id = :org_id AND created_at &gt;= DATEADD(minute, -5, CURRENT_TIMESTAMP()));$$;Consolidated

FROM COPY/ingest AND staged-file registration ideas in the Snowflake delivery patterns

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.proc_docgen_99_purge_followups_older_than_days (org_id STRING, days INT)RETURNS NUMBER
LANGUAGE SQL
AS $$DELETE FROM AI_FEATURE_HUB.docgen_feature_instance_incident_followups WHERE org_id = :org_id AND created_at &lt; DATEADD(day, -:days, CURRENT_TIMESTAMP());RETURN (SELECT ROW_COUNT());$$;Consolidated

FROM purge/retention AND ROW_COUNT idioms in the provided artifacts

