AIFEATUREHUB.procdocgen4216_process_feature_instance_cost_reallocation_requestPurpose: process (approve/deny)a cost reallocation request, INSERT audit, UPDATE request status;
RETURNS auditid.

-- ---- PROCEDURE boundary ----
;

CREATE OR REPLACE PROCEDURE AIFEATUREHUB.procdocgen4216_process_feature_instance_cost_reallocation_request (auditid STRING, requestid STRING, instanceref STRING, featurekey STRING, orgid STRING, processedby STRING, action STRING, -- e.g., &#39;APPROVE&#39; OR &#39;DENY&#39;  notes VARIANT)RETURNS STRINGLANGUAGE SQLAS$$-- Insert audit recordINSERT INTO AIFEATUREHUB.docgen4215featureinstancecostreallocationaudit  (auditid, requestid, instanceref, featurekey, orgid, processedby, action, notes, actedat)VALUES  (:auditid, :requestid, :instanceref, :featurekey, :orgid, :processedby, :action, :notes, CURRENT_TIMESTAMP());
-- Update request status accordinglyUPDATE AIFEATUREHUB.docgen4213featureinstancecostreallocationrequestsSET status = CASE WHEN UPPER(:action) = &#39;APPROVE&#39; THEN &#39;APPROVED&#39;                  WHEN UPPER(:action) = &#39;DENY&#39; THEN &#39;DENIED&#39;                  ELSE status END,    processedat = CASE WHEN UPPER(:action) IN (&#39;APPROVE&#39;,&#39;DENY&#39;) THEN CURRENT_TIMESTAMP() ELSE processedat END,    processedby = CASE WHEN UPPER(:action) IN (&#39;APPROVE&#39;,&#39;DENY&#39;) THEN :processedby ELSE processedby ENDWHERE requestid = :requestid;
RETURN :auditid;$$;

