CREATE OR REPLACE PROCEDURE AIFEATUREHUB.proc_docgen_feature_instance_third_party_integration_configs_insert (id STRING, integration_type STRING, config VARIANT, instance_ref STRING DEFAULT NULL, feature_key STRING DEFAULT NULL, org_id STRING DEFAULT NULL)RETURNS STRINGLANGUAGE SQLAS$$MERGE INTO AIFEATUREHUB.docgen_feature_instance_third_party_integration_configs tgtUSING (SELECT :id AS id) src ON tgt.id = src.idWHEN MATCHED THEN UPDATE SET integration_type = :integration_type, config = :config, instance_ref = :instance_ref, feature_key = :feature_key, org_id = :org_id, updated_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT (id, integration_type, config, instance_ref, feature_key, org_id, created_at) VALUES (:id, :integration_type, :config, :instance_ref, :feature_key, :org_id, CURRENT_TIMESTAMP());RETURN :id;$$;Source:

