;

CREATE OR REPLACE PROCEDURE AI_FEATURE_HUB.CLAIM_INGEST_MANIFEST (manifest_id STRING, worker_id STRING, ttl_seconds INT)RETURNS STRINGLANGUAGE SQLAS $$MERGE INTO AI_FEATURE_HUB.ingest_manifest_claims tgtUSING (SELECT :manifest_id AS manifest_id) srcON tgt.manifest_id = src.manifest_idWHEN MATCHED AND tgt.expires_at &lt; CURRENT_TIMESTAMP() THEN UPDATE SET worker_id = :worker_id, expires_at = DATEADD(second, :ttl_seconds, CURRENT_TIMESTAMP()), claimed_at = CURRENT_TIMESTAMP()WHEN NOT MATCHED THEN INSERT (claim_id, manifest_id, worker_id, expires_at, claimed_at) VALUES (SYSTEM$UUID(), :manifest_id, :worker_id, DATEADD(second, :ttl_seconds, CURRENT_TIMESTAMP()), CURRENT_TIMESTAMP());RETURN :manifest_id;$$;

